import json, statistics
from pathlib import Path
root=Path('benchmark'); data=json.loads((root/'results.json').read_text())
rows=data['results']
summary={'shots':len(rows),'medianInferenceSeconds':statistics.median(r['inferenceSeconds'] for r in rows),'medianTotalSeconds':statistics.median(r['totalSeconds'] for r in rows),'totalSeconds':sum(r['totalSeconds'] for r in rows),'device':data['device'],'peakProcessMB':data['peakProcessMB']}
(root/'summary.json').write_text(json.dumps(summary,indent=2))
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>EDITMAP · Model review</title><style>body{background:#141618;color:#dce0e2;font:15px system-ui;margin:28px}h1{font-size:24px}p{color:#a7b1b8;max-width:1000px;line-height:1.6}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px}article{background:#202528;border:1px solid #3b4248;padding:14px}img{width:100%;aspect-ratio:4/3;object-fit:fill}select,button{background:#30383d;color:white;border:1px solid #637078;padding:9px;margin:8px 0}small{color:#a7b1b8}header{position:sticky;top:0;background:#141618;padding:8px;z-index:1}label{display:block}strong{color:#d5bb81}</style><h1>EDITMAP / Shot-size benchmark</h1><p>40 shots sampled across How to Shoot a Ghost. Predictions are experimental, not verified tags. Review the frame, choose your reference label, then export the review. The displayed frame is the middle of the 16 model samples; the model sees the full sampled sequence. Mixed or unjudgeable shots can be excluded.</p><p>ECS = extreme close-up · CS = close-up · MS = medium · FS = full shot · LS = long shot. These five categories do not cover every EDITMAP label.</p><p id="timing"></p><header><b id="score"></b> <button id="export">Export reviewed labels</button></header><div class="grid" id="grid"></div><script>const data=DATA;const summary=SUMMARY;const key='editmap-benchmark-ghost-v1';let labels={};try{labels=JSON.parse(localStorage.getItem(key)||'{}')}catch{}const classes=['ECS','CS','MS','FS','LS'];document.querySelector('#timing').textContent=`Device: ${summary.device} · Median inference: ${summary.medianInferenceSeconds.toFixed(2)}s/shot · Median including decoding: ${summary.medianTotalSeconds.toFixed(2)}s/shot · Peak process memory: ${summary.peakProcessMB.toFixed(0)} MB (GPU memory is separate).`;function score(){let n=0,correct=0;for(const r of data.results){if(classes.includes(labels[r.index])){n++;if(labels[r.index]===r.prediction)correct++;}}document.querySelector('#score').textContent=n?`${n} reviewed · ${correct}/${n} match (${(correct/n*100).toFixed(1)}%)`:'Accuracy not measured — add reference labels below';}for(const r of data.results){const card=document.createElement('article');card.innerHTML=`<img src="shot-${r.index}.jpg" alt="Sample from shot ${r.index}"><h3>Shot ${r.index} · <strong>${r.prediction}</strong></h3><p>${r.start} · ${r.duration.toFixed(2)}s</p><small>Model score ${(Math.max(...Object.values(r.scores))*100).toFixed(1)}% — not calibrated confidence</small><label>Your reference label <select><option value="">Not reviewed</option><option>ECS</option><option>CS</option><option>MS</option><option>FS</option><option>LS</option><option>Mixed / unclear</option></select></label>`;const select=card.querySelector('select');select.value=labels[r.index]||'';select.onchange=()=>{labels[r.index]=select.value;try{localStorage.setItem(key,JSON.stringify(labels))}catch{}score()};document.querySelector('#grid').append(card);}score();document.querySelector('#export').onclick=()=>{const blob=new Blob([JSON.stringify({...data,referenceLabels:labels},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='editmap-model-review.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};</script></html>'''
html=html.replace('DATA',json.dumps(data)).replace('SUMMARY',json.dumps(summary))
(root/'review.html').write_text(html)
print(json.dumps(summary,indent=2))
